for op,v in a['aggregate'].items():
 t=v['timing'];over=t[1]['over_budget_rate'];lines.append(f"|{op}|{v['point']:.4f} {v['point_ci95']}|{v['difference']:+.4f} {v['difference_ci95']}|{t[0]['mean_ms']:.3f}/{t[1]['mean_ms']:.3f}|{'適用なし' if over is None else f'{over:.3%}'}|")
lines+=['','pointは勝1/引分0.5/負0。2座席と3seedをprefix内平均して96prefix単位bootstrap（4000回）。固定モデル条件のCIであり更新seed母集団CIではない。ネット単体にはdeadlineがなく、同時間比較ではない。教師cost/refine予測は各試合cold。時間計測を学習・監査・敗局解析から分離し、計測後に再生監査した。超過は全act実時間が相手の6/100ms上限を超えた割合。モデル初期化/warmupは従来通り別。','', '|seed/相手|勝/敗/分|point|得点差 [95% CI]|','|---|---|---|---|']
for name,v in a['individual'].items():
 s=v['summary'];lines.append(f"|{name}|{s['wins']}/{s['losses']}/{s['draws']}|{s['point_rate']:.4f}|{s['mean_difference']:+.4f} {v['clustered']['difference_ci95']}|")
lines+=['','## main提供条件','', f"事前gate clear_regression={a['clear_regression']}、PPO CLI既定世代={a['default_generation']}。3seed/checkpointは再選択しない。旧2048と既存value/2ply・100ms教師を残す。グローバル旧AIデフォルト不変、PPO seed既定1401も維持。新世代推論checkpointは履歴/RNG/optimizer不要、研究履歴の複製なし。CPU/CUDA export前後の一致・新clone検証はexport-check.json/fresh-clone.jsonを参照。", '', '## 少数敗局の記述的診断','', '各seed×対2048/教師100msの最初の敗局1局、計6局。絶対ply<14/14〜27/28以上を序盤/中盤/終盤とし、各期最初の自手番（pass以外）を採取。選択バイアスの強い標本であり頻度推定・因果推定には使わない。参照は固定value alpha=.5/gate24、heuristic上位128root＋実際の手、相手上位3応手の完了2plyで、真のゲーム価値ではない。', '', '|phase|標本数|平均参照値gap|平均heuristic順位|正gap数|','|---|---|---|---|---|']
