for op,v in a['aggregate'].items():s+=f"|{op}|{v['point']:.3f} {v['point_ci95']}|{v['difference']:+.3f} {v['difference_ci95']}|{v['timing'][0]['mean_ms']:.3f}/{v['timing'][1]['mean_ms']:.3f}|\n"
